export function Elevation({
  level = "{{level}}",
  background = "{{background}}",
  radius = {{radius}},
  size = {{size}},
}) {
  const shadows = {
    "0": { boxShadow: "none", transform: "translateY(0)" },
    "1": { boxShadow: "0 2px 6px rgba(36,20,48,.18)", transform: "translateY(-1px)" },
    "2": { boxShadow: "0 8px 18px rgba(36,20,48,.22)", transform: "translateY(-4px)" },
    "3": { boxShadow: "0 18px 36px rgba(36,20,48,.28)", transform: "translateY(-8px)" },
  }[level];
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A card floating higher above the surface as its elevation level increases, shown by a longer, softer shadow and a small upward shift">
      <div style={{ background: "#24143011", borderRadius: 12, padding: "32px 20px", display: "flex", justifyContent: "center" }}>
        <div style={{ width: size, height: size, background, borderRadius: radius, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, ...shadows }}>
          level {level}
        </div>
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>elevation level {level} of 3</p>
    </div>
  );
}
